28	// WriteHookResponse outputs a JSON hook response to stdout.
29	// Claude Code reads this JSON and displays the systemMessage to the user.
30	func (c *ClaudeCodeAgent) WriteHookResponse(message string) error {
31		resp := struct {
32			SystemMessage string `json:"systemMessage,omitempty"`
33		}{SystemMessage: message}
34		if err := json.NewEncoder(os.Stdout).Encode(resp); err != nil {
35			return fmt.Errorf("failed to encode hook response: %w", err)
36		}
37		return nil
38	}
