87	// PrepareTranscript waits for Claude Code's async transcript flush to complete.
88	// Claude writes a hook_progress sentinel entry after flushing all pending writes.
89	func (c *ClaudeCodeAgent) PrepareTranscript(ctx context.Context, sessionRef string) error {
90		waitForTranscriptFlush(ctx, sessionRef, time.Now())
91		return nil
92	}
