191	// resolveTranscriptPath returns the canonical path to a Claude transcript file,
192	// recovering from the Claude Code worktree-feature mismatch where
193	// transcript_path encodes the worktree CWD (e.g. .claude/worktrees/<branch>) but
194	// the file is stored under the parent repo's project dir. Falls back to scanning
195	// ~/.claude/projects/*/<sessionID>.jsonl when the reported path doesn't exist.
196	//
197	// The fallback is gated to keep cost and risk minimal:
198	//   - Only triggers on os.IsNotExist (permission/IO errors are returned as-is so
199	//     real problems aren't masked by a scan).
200	//   - Only triggers when the reported path is under the Claude projects base
201	//     dir; for any other path the scan can't produce a better answer.
202	//   - The session ID is validated with validation.ValidateAgentSessionID before
203	//     being used in filepath.Join, blocking traversal via hostile hook input.
204	func (c *ClaudeCodeAgent) resolveTranscriptPath(sessionRef, sessionID string) string {
205		if sessionRef == "" || sessionID == "" {
206			return sessionRef
207		}
208		if _, err := os.Stat(sessionRef); err == nil {
209			return sessionRef
210		} else if !os.IsNotExist(err) {
211			return sessionRef
212		}
213		if err := validation.ValidateAgentSessionID(sessionID); err != nil {
214			return sessionRef
215		}
216		base, err := c.GetSessionBaseDir()
217		if err != nil {
218			return sessionRef
219		}
220		cleanedRef := filepath.Clean(sessionRef)
221		cleanedBase := filepath.Clean(base)
222		if !strings.HasPrefix(cleanedRef, cleanedBase+string(os.PathSeparator)) {
223			return sessionRef
224		}
225		found := findTranscriptByID(cleanedBase, sessionID)
226		if found == "" {
227			return sessionRef
228		}
229		logging.Info(logging.WithComponent(context.Background(), "agent.claudecode"),
230			"resolved transcript via fallback scan",
231			slog.String("reported", sessionRef),
232			slog.String("found", found),
233			slog.String("session_id", sessionID),
234		)
235		return found
236	}
237	
238	// findTranscriptByID scans baseDir's immediate child directories for a file
239	// named "<sessionID>.jsonl" and returns the first match, or "" if none.
240	// Callers must validate sessionID with validation.ValidateAgentSessionID first
241	// — this function trusts the input and uses it verbatim in filepath.Join.
242	func findTranscriptByID(baseDir, sessionID string) string {
243		entries, err := os.ReadDir(baseDir)
244		if err != nil {
245			return ""
246		}
247		fname := sessionID + ".jsonl"
248		for _, e := range entries {
249			if !e.IsDir() {
250				continue
251			}
252			candidate := filepath.Join(baseDir, e.Name(), fname)
253			if _, err := os.Stat(candidate); err == nil {
254				return candidate
255			}
256		}
257		return ""
258	}
