260	// --- Transcript flush sentinel ---
261	
262	// stopHookSentinel is the string that appears in Claude Code's hook_progress
263	// entry when the stop hook has been invoked, indicating the transcript is fully flushed.
264	const stopHookSentinel = "hooks claude-code stop"
265	
266	// waitForTranscriptFlush polls the transcript file for the stop hook sentinel.
267	// Falls back silently after a timeout.
268	func waitForTranscriptFlush(ctx context.Context, transcriptPath string, hookStartTime time.Time) {
269		const (
270			maxWait      = 3 * time.Second
271			pollInterval = 50 * time.Millisecond
272			tailBytes    = 4096
273			maxSkew      = 2 * time.Second
274		)
275	
276		logCtx := logging.WithComponent(ctx, "agent.claudecode")
277	
278		// Fast path: skip the poll loop when the sentinel can't possibly appear.
279		// - File doesn't exist: nothing to poll.
280		// - File is stale (unmodified for 2+ min): agent isn't running anymore.
281		//   This avoids 3s timeouts per stale "active" session (e.g., agent crashed
282		//   without firing stop hook).
283		const staleThreshold = 2 * time.Minute
284		info, err := os.Stat(transcriptPath)
285		if err != nil {
286			// Most likely the file doesn't exist; other errors (permission, etc.)
287			// would also prevent polling, so skip the wait either way.
288			return
289		}
290		fileAge := time.Since(info.ModTime())
291		if fileAge > staleThreshold {
292			logging.Debug(logCtx, "transcript file is stale, skipping sentinel wait",
293				slog.Duration("file_age", fileAge),
294			)
295			return
296		}
297	
298		deadline := time.Now().Add(maxWait)
299		for time.Now().Before(deadline) {
300			if checkStopSentinel(transcriptPath, tailBytes, hookStartTime, maxSkew) {
301				logging.Debug(logCtx, "transcript flush sentinel found",
302					slog.Duration("wait", time.Since(hookStartTime)),
303				)
304				return
305			}
306			time.Sleep(pollInterval)
307		}
308		logging.Warn(logCtx, "transcript flush sentinel not found within timeout, proceeding",
309			slog.Duration("timeout", maxWait),
310		)
311	}
312	
313	// checkStopSentinel reads the tail of the transcript file and looks for the sentinel.
314	func checkStopSentinel(path string, tailBytes int64, hookStartTime time.Time, maxSkew time.Duration) bool {
315		f, err := os.Open(path) //nolint:gosec // path comes from agent hook input
316		if err != nil {
317			return false
318		}
319		defer f.Close()
320	
321		info, err := f.Stat()
322		if err != nil {
323			return false
324		}
325		offset := info.Size() - tailBytes
326		if offset < 0 {
327			offset = 0
328		}
329		buf := make([]byte, info.Size()-offset)
330		if _, err := f.ReadAt(buf, offset); err != nil {
331			return false
332		}
333	
334		lines := strings.Split(string(buf), "\n")
335		for _, line := range lines {
336			line = strings.TrimSpace(line)
337			if line == "" || !strings.Contains(line, stopHookSentinel) {
338				continue
339			}
340	
341			var entry struct {
342				Timestamp string `json:"timestamp"`
343			}
344			if json.Unmarshal([]byte(line), &entry) != nil || entry.Timestamp == "" {
345				continue
346			}
347			ts, err := time.Parse(time.RFC3339Nano, entry.Timestamp)
348			if err != nil {
349				ts, err = time.Parse(time.RFC3339, entry.Timestamp)
350				if err != nil {
351					continue
352				}
353			}
354			// Validate timestamp is within acceptable range:
355			// - Not too far in the past (before hook started minus skew)
356			// - Not too far in the future (after hook started plus skew)
357			lowerBound := hookStartTime.Add(-maxSkew)
358			upperBound := hookStartTime.Add(maxSkew)
359			if ts.After(lowerBound) && ts.Before(upperBound) {
360				return true
361			}
362		}
363		return false
364	}
