94	// GetSessionDir returns the directory where Claude stores session transcripts.
95	func (c *ClaudeCodeAgent) GetSessionDir(repoPath string) (string, error) {
96		// Check for test environment override
97		if override := os.Getenv("ENTIRE_TEST_CLAUDE_PROJECT_DIR"); override != "" {
98			return override, nil
99		}
100	
101		homeDir, err := os.UserHomeDir()
102		if err != nil {
103			return "", fmt.Errorf("failed to get home directory: %w", err)
104		}
105	
106		projectDir := SanitizePathForClaude(repoPath)
107		return filepath.Join(homeDir, ".claude", "projects", projectDir), nil
108	}
