489	func TestWaitForTranscriptFlush_StaleFile_SkipsWait(t *testing.T) {
490		t.Parallel()
491	
492		// Create a transcript file and backdate its mtime to make it "stale"
493		transcriptFile := filepath.Join(t.TempDir(), "transcript.jsonl")
494		if err := os.WriteFile(transcriptFile, []byte(`{"type":"human"}`+"\n"), 0o644); err != nil {
495			t.Fatalf("failed to write transcript: %v", err)
496		}
497		staleTime := time.Now().Add(-10 * time.Minute)
498		if err := os.Chtimes(transcriptFile, staleTime, staleTime); err != nil {
499			t.Fatalf("failed to set mtime: %v", err)
500		}
501	
502		// waitForTranscriptFlush should return almost instantly for stale files
503		// (not wait the full 3 seconds)
504		start := time.Now()
505		waitForTranscriptFlush(context.Background(), transcriptFile, time.Now())
506		elapsed := time.Since(start)
507	
508		if elapsed > 500*time.Millisecond {
509			t.Errorf("expected fast return for stale transcript, but took %v", elapsed)
510		}
511	}
